mapper.select:
SELECT o.*, g.book_name as goods_name, SUBSTRING_INDEX(g.images, ',', 1) as goods_image, seller.nick_name as seller_name, seller.avatar as seller_avatar FROM `order` o LEFT JOIN goods g ON o.goods_id = g.id LEFT JOIN user seller ON o.seller_id = seller.id WHERE o.buyer_id = #{buyerId}
AND o.status = #{status}
ORDER BY o.create_time DESC
LIMIT #{offset}, #{limit}

SELECT o.*, g.book_name as goods_name, SUBSTRING_INDEX(g.images, ',', 1) as goods_image, buyer.nick_name as buyer_name, buyer.avatar as buyer_avatar FROM `order` o LEFT JOIN goods g ON o.goods_id = g.id LEFT JOIN user buyer ON o.buyer_id = buyer.id WHERE o.seller_id = #{sellerId}
AND o.status = #{status}
ORDER BY o.create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM `order`
WHERE goods_id = #{goodsId}
AND status IN (0, 1)

mapper.update:
UPDATE `order`
SET status = #{status},
    update_time = NOW()


            , confirm_time = #{updateFields.confirmTime}


            , finish_time = #{updateFields.finishTime}


            , cancel_time = #{updateFields.cancelTime}


            , cancel_reason = #{updateFields.cancelReason}


            , cancel_by = #{updateFields.cancelBy}


WHERE id = #{id}
